import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";

export class GridSpatial {

    /**
     * Get valid map tiles within a certain radius of a center point.
     * Used for game logic (e.g. finding targets) to ensure we don't pick void tiles.
     */
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        // Use HexUtils instead of direct HexMath
        const candidates = HexUtils.range({q: centerQ, r: centerR}, radius);
        const valid: Hex[] = [];

        for (const hex of candidates) {
            if (engine.map.isValid(hex.q, hex.r)) {
                valid.push(hex);
            }
        }
        return valid;
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        // Raycast down from max possible height
        for (let h = 0; h <= maxHeight; h += step) {
            // "Unproject" the Y coordinate by adding height (since visual Y = ground Y - height)
            const testY = wy + h; 

            // Simplified: Delegate projection math to HexUtils
            const rounded = HexUtils.fromPx(wx, testY, engine.mapConfig);
            const key = HexUtils.key(rounded);

            const tile = cache.tileMap.get(key);

            if (tile) {
                // Check if the click hits the top face or the slope
                // Visual Y of the tile top is (py - tile.h)
                const visualTopY = tile.py - tile.h;

                // Distance check in screen space roughly
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                // Tighter hit box for better precision
                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    // We found a candidate. The tile with the highest visual Z (closest to camera) should win.
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    /**
     * Detection for "X-Ray" Silhouette Rendering.
     * Identifies agents that are hidden behind taller terrain relative to the camera.
     */
    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        const layout = engine.mapConfig.layout;

        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;

            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);
            // Height of the unit's head (approx)
            const unitHeadH = uTerrainH + 60; 

            // Check neighbors that are "closer" to the camera (High Y in screen space).
            // In Hex grid, these are usually:
            // FLAT: (q, r+1), (q+1, r)
            // POINTY: (q, r+1), (q+1, r), (q-1, r+1) etc.

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            // We define "South" as neighbors that would be drawn AFTER the current tile.
            // In the render sort (q+r), larger values are drawn later (in front).
            const currentSort = a.q + a.r;

            for (const n of neighbors) {
                const nSort = n.q + n.r;

                // Only check tiles that are strictly "in front" (rendering wise)
                if (nSort > currentSort) {
                    const k = HexUtils.key(n);

                    // Check if map tile exists
                    if (engine.mapKeys.has(k)) {
                        const nTerrainH = engine.map.getTerrainHeight(n.q, n.r);

                        // Condition: The terrain in front is taller than the unit's current ground level
                        // Threshold: Must be at least BLOCK_HEIGHT taller to cause occlusion
                        if (nTerrainH > uTerrainH + 10) {

                            // Specific check: Is it taller than the unit's HEAD?
                            // If taller than head -> Full occlusion
                            // If taller than feet but lower than head -> Partial (we can still enable silhouette for clarity)

                            // Visual tweak: If terrain is significantly higher, trigger silhouette
                            if (nTerrainH > uTerrainH + 20) {
                                occluded.push(a);
                                break; // Found one occluder, that's enough
                            }
                        }
                    }
                }
            }
        }
        return occluded;
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { HazardPainter } from "./grid/painters/HazardPainter"; 
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;

        ctx.resetTransform(); 

        // Fallback Fill: If background renderer fails, at least show a dark void, not transparency
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, physicalWidth, physicalHeight);

        ctx.scale(dpr, dpr);

        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();

        // 1. Main Geometry Pass
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr, globalTime, layout, op.ttheme);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, undefined, layout);
                    break;
                case RenderOpType.HAZARD: 
                    if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 2. Occlusion Silhouette Pass (X-Ray)
        // This must happen AFTER all terrain/obstacles are drawn to appear "on top"
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            // Setup X-Ray Context
            ctx.save();
            ctx.globalCompositeOperation = 'source-over'; // Normal blending on top

            occludedAgents.forEach(agent => {
                // Determine logic for this agent
                // We re-use UnitRenderSystem but with a special flag
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });

            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
function easeAttack(t: number): number {
    if (t < 0.3) {
        const p = t / 0.3;
        return -0.25 * (p * p); 
    } else if (t < 0.45) {
        const p = (t - 0.3) / 0.15;
        return -0.25 + (1.35 * (p * p * p)); 
    } else {
        const p = (t - 0.45) / 0.55;
        return 1.1 * Math.cos(p * Math.PI / 2);
    }
}
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = THEME_IMPERIAL.energy; // Cyan for Imperial
        const breathePhase = t * 2.0;
        const floatY = (agent.hp > 0) ? Math.sin(breathePhase) * 2.5 : 0;
        const breatheScale = (agent.hp > 0) ? 1.0 + Math.sin(breathePhase) * 0.02 : 1.0;
        let hitShakeRot = 0;
        let hitSquashX = 1.0;
        let hitSquashY = 1.0;
        if (agent.hitFlashTimer > 0) {
            hitShakeRot = (Math.random() - 0.5) * 0.15; 
            const trauma = agent.hitFlashTimer * 5; 
            hitSquashY = 1.0 - (trauma * 0.15);
            hitSquashX = 1.0 + (trauma * 0.1);
        }
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoilX = 0;
        let bodyRecoilY = 0;
        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);
            const curve = easeAttack(p);
            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                const kick = Math.max(0, curve);
                armX = kick * 12;
                if (p > 0.3 && p < 0.6) bodyRecoilX = -4 * kick;
                if (p < 0.3) armRot = -0.3 * (p/0.3); 
            } else {
                armRot = curve * (Math.PI / 1.6); 
                if (curve > 0.5) {
                    armX = 18 * curve;
                    bodyRecoilX = 5 * curve; 
                } else if (curve < 0) {
                    bodyRecoilX = -2;
                }
            }
        }
        ctx.save();

        // --- SILHOUETTE PASS (X-RAY) ---
        if (isSilhouette) {
            ctx.translate(bodyRecoilX, floatY);

            // Draw simplified shape for outline
            ctx.shadowColor = silhouetteColor;
            ctx.shadowBlur = 10;
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;

            // X-Ray Fill
            ctx.fillStyle = silhouetteColor;
            ctx.globalAlpha = 0.2; // Transparent body

            ctx.beginPath();
            // Simplified "Pawn" shape
            if (agent.role === Role.TANK) {
                ctx.moveTo(-15, -50); ctx.lineTo(15, -50);
                ctx.lineTo(10, 0); ctx.lineTo(-10, 0);
            } else {
                ctx.moveTo(-10, -50); ctx.lineTo(10, -50);
                ctx.lineTo(5, 0); ctx.lineTo(-5, 0);
            }
            ctx.closePath();
            ctx.fill();

            ctx.globalAlpha = 0.8; // Solid outline
            ctx.stroke();

            // Role Icon Hint above head
            ctx.beginPath();
            ctx.arc(0, -60, 4, 0, Math.PI*2);
            ctx.fill();

            ctx.restore();
            return;
        }

        // --- NORMAL RENDER ---
        ctx.translate(bodyRecoilX, floatY + bodyRecoilY);
        ctx.translate(0, -40); 
        ctx.rotate(hitShakeRot);
        ctx.scale(breatheScale * hitSquashX, breatheScale * hitSquashY);
        ctx.translate(0, 40);
        drawCape(ctx, t, THEME_IMPERIAL.cape, bodyRecoilX);
        ctx.save();
        ctx.translate(-20, -35);
        ctx.translate(0, Math.sin(t * 2.5 + Math.PI) * 2); 
        if (agent.role === Role.TANK) drawImperialShield(ctx);
        else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) drawImperialTome(ctx, t);
        ctx.restore();
        drawImperialBody(ctx, agent.role);
        ctx.save();
        ctx.translate(20, -35);
        ctx.rotate(armRot);
        ctx.translate(armX, armY);
        drawImperialWeapon(ctx, agent.role, t);
        ctx.restore();
        ctx.restore();
    }
};
function drawImperialBody(ctx: CanvasRenderingContext2D, role: Role) {
    const { primary, secondary, armorLight, armorDark } = THEME_IMPERIAL;
    const grad = ctx.createLinearGradient(-15, -50, 15, 0);
    grad.addColorStop(0, armorLight);
    grad.addColorStop(0.5, armorDark);
    grad.addColorStop(1, primary);
    ctx.fillStyle = grad;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    if (role === Role.TANK) {
        ctx.moveTo(-22, -45); ctx.lineTo(22, -45);
        ctx.lineTo(15, 0); ctx.lineTo(-15, 0);
        ctx.lineTo(-22, -45);
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
        ctx.lineTo(18, 10); ctx.lineTo(-18, 10);
        ctx.lineTo(-12, -45);
    } else {
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
        ctx.lineTo(-18, -45);
