            const curve = easeAttack(p);
            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                const jerk = Math.max(0, curve);
                armX = jerk * 25; 
                if (p > 0.4 && p < 0.6) {
                    bodyRecoilX = -8; 
                    bodyRecoilY = (Math.random() - 0.5) * 4;
                }
            } else {
                armRot = curve * (Math.PI / 1.3);
                if (curve > 0) {
                    armX = 25 * curve;
                    armY = 15 * curve; 
                    bodyRecoilX = 10 * curve; 
                    bodyRot = 0.1 * curve; 
                } else {
                    bodyRecoilX = -5; 
                    bodyRot = -0.1;   
                }
            }
        }
        ctx.save();

        // --- SILHOUETTE PASS (X-RAY) ---
        if (isSilhouette) {
            ctx.translate(bodyRecoilX, floatY);

            // Red Outline
            ctx.shadowColor = silhouetteColor;
            ctx.shadowBlur = 10;
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;

            // X-Ray Fill
            ctx.fillStyle = silhouetteColor;
            ctx.globalAlpha = 0.2;

            ctx.beginPath();
            // Simplified "Spikey" shape
            ctx.moveTo(-15, -60); ctx.lineTo(0, -70); ctx.lineTo(15, -60);
            ctx.lineTo(10, 0); ctx.lineTo(-10, 0); 
            ctx.closePath();
            ctx.fill();

            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // Spikes hint
            ctx.beginPath();
            ctx.moveTo(-20, -40); ctx.lineTo(-5, -45);
            ctx.moveTo(20, -40); ctx.lineTo(5, -45);
            ctx.lineWidth = 1;
            ctx.stroke();

            ctx.restore();
            return;
        }

        // --- NORMAL RENDER ---
        ctx.translate(bodyRecoilX + hitShakeX, floatY + bodyRecoilY);
        ctx.translate(0, -40); 
        ctx.rotate(hitShakeRot + bodyRot);
        ctx.scale(breatheScaleX, breatheScaleY * hitSquashY);
        ctx.translate(0, 40);
        drawSpikes(ctx, t);
        ctx.save();
        ctx.translate(-22, -30);
        ctx.translate(0, Math.sin(t * 3) * 2);
        if (agent.role === Role.TANK) drawCovenantShield(ctx);
        else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) drawCovenantTotem(ctx, t);
        ctx.restore();
        drawCovenantBody(ctx, agent.role);
        ctx.save();
        ctx.translate(22, -30);
        ctx.rotate(armRot);
        ctx.translate(armX, armY);
        drawCovenantWeapon(ctx, agent.role, t);
        ctx.restore();
        ctx.restore();
    }
};
function drawCovenantBody(ctx: CanvasRenderingContext2D, role: Role) {
    const { primary, armorDark, armorBase, accent, secondary } = THEME_COVENANT;
    const grad = ctx.createLinearGradient(-15, -50, 15, 10);
    grad.addColorStop(0, primary);
    grad.addColorStop(0.6, armorDark);
    grad.addColorStop(1, '#000');
    ctx.fillStyle = grad;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (role === Role.TANK) {
        ctx.moveTo(-25, -40); ctx.lineTo(25, -40); 
        ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
        ctx.lineTo(-25, -40);
    } else {
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(8, 15); ctx.lineTo(-8, 15);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -35);
    ctx.lineTo((Math.random()-0.5)*5, -25);
    ctx.lineTo(0, -15);
    ctx.stroke();
    ctx.save();
    ctx.translate(0, -48);
    ctx.fillStyle = armorDark;
    ctx.beginPath();
    ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
    ctx.lineTo(5, -5); ctx.lineTo(12, -15); ctx.lineTo(10, 5);
    ctx.fill();
    ctx.fillStyle = '#fca5a5';
    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();
    ctx.restore();
}
function drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
    ctx.save();
    ctx.translate(0, -40);
    ctx.fillStyle = THEME_COVENANT.spike;
    ctx.beginPath();
    ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + Math.sin(t*5)*2); ctx.lineTo(-15, 0);
    ctx.moveTo(10, 0); ctx.lineTo(20, -25 + Math.cos(t*4)*2); ctx.lineTo(15, 0);
    ctx.fill();
    ctx.restore();
}
function drawCovenantHand(ctx: CanvasRenderingContext2D) {
    ctx.fillStyle = THEME_COVENANT.armorDark;
    ctx.beginPath(); 
    ctx.moveTo(-6, -6); ctx.lineTo(6, -6); ctx.lineTo(4, 8); ctx.lineTo(-4, 8);
    ctx.fill();
}
function drawCovenantShield(ctx: CanvasRenderingContext2D) {
    drawCovenantHand(ctx);
    ctx.translate(-5, 10);
    ctx.fillStyle = THEME_COVENANT.armorBase;
    ctx.strokeStyle = THEME_COVENANT.secondary;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(-15, -25); ctx.lineTo(15, -20);
    ctx.lineTo(20, 0); ctx.lineTo(10, 25);
    ctx.lineTo(-15, 20); ctx.lineTo(-20, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = THEME_COVENANT.accent;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -35); ctx.lineTo(5, -10); ctx.fill();
}
function drawCovenantTotem(ctx: CanvasRenderingContext2D, t: number) {
    drawCovenantHand(ctx);
    ctx.translate(0, 10);
    ctx.fillStyle = '#3f3f46';
    ctx.fillRect(-4, -40, 8, 50);
    ctx.translate(0, -45);
    ctx.fillStyle = THEME_COVENANT.secondary;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10);
    ctx.fill();
}
function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawCovenantHand(ctx);
    if (role === Role.WARRIOR) {
        ctx.rotate(Math.PI / 4);
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.fillRect(-3, -10, 6, 60);
        ctx.translate(0, -60);
        ctx.fillStyle = '#52525b';
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(-25, -10);
        ctx.quadraticCurveTo(-15, 10, -25, 30);
        ctx.lineTo(0, 20);
        ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 5); ctx.lineTo(0, 10); ctx.fill();
    } else if (role === Role.TANK) {
        ctx.rotate(Math.PI / 3);
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.fillRect(-4, -5, 8, 20);
        ctx.fillStyle = THEME_COVENANT.accent;
        ctx.beginPath();
        ctx.moveTo(-10, -10); ctx.lineTo(-10, -60);
        ctx.lineTo(20, -60); ctx.lineTo(20, -10); ctx.lineTo(0, 0);
        ctx.fill();
        ctx.strokeStyle = THEME_COVENANT.secondary; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(20, -60); ctx.lineTo(20, -10); ctx.stroke();
    } else if (role === Role.RANGER) {
        ctx.rotate(-Math.PI / 2);
        ctx.fillStyle = THEME_COVENANT.armorDark;
        ctx.fillRect(-5, -30, 10, 40);
        ctx.strokeStyle = THEME_COVENANT.accent; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, -30); ctx.lineTo(25, -25); ctx.stroke();
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, 0); ctx.lineTo(25, -25); ctx.stroke();
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.rotate(Math.PI / 6);
        ctx.fillStyle = '#450a0a';
        ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(-5, -30); ctx.lineTo(0, -50); ctx.lineTo(5, -30); ctx.fill();
        ctx.fillStyle = THEME_COVENANT.secondary;
        ctx.beginPath(); ctx.arc(0, -50, 3, 0, Math.PI*2); ctx.fill();
    }
}

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. 獲取身體中心視覺 Y 軸 (SSOT)
        // 直接讀取 Agent 物理狀態，避免外部傳遞錯誤
        const pz = agent.physics.z;
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. 核心受擊幾何處理 (Juice Math)
        let hitBrightness = 0;
        let squashX = 1.0;
        let squashY = 1.0;

        if (agent.hitFlashTimer > 0 && !isSilhouette) {
            const trauma = agent.hitFlashTimer / 0.2; // 歸一化進度
            // 數學擠壓：受擊時垂直縮短，水平伸長
            squashY = 1.0 - (trauma * 0.25);
            squashX = 1.0 + (trauma * 0.15);
            // 亮度震盪函數 (高頻率 40Hz)
            hitBrightness = 100 + Math.sin(t * 40) * 50;
        }

        ctx.scale(UNIT_SCALE * squashX, UNIT_SCALE * squashY);
        ctx.rotate(agent.physics.angle); 

        // 3. 基礎呼吸與浮動 (Silhouette needs float but not breath scale usually, 
        //    but keeping sync is safer for outline matching)
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 4. 進場縮放動畫
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 5. 狀態濾鏡應用
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(70%)'; 
        } else if (hitBrightness > 0) {
             ctx.filter = `brightness(${hitBrightness}%) contrast(120%)`;
        }

        // 6. 飛行與特殊模型渲染
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (agent.visualStatus === 'POLYMORPH' && !isSilhouette) {
            // Polymorph usually doesn't have an x-ray outline since it's a joke state, 
            // but we skip it here for simplicity or could add simple circle.
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (agent.visualStatus === 'FROZEN' && !isSilhouette) {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

export type ParticleType = 'SPARK' | 'SMOKE' | 'SMOKE_PUFF' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'BLAST' | 'CHIP' | 'PILLAR' | 'HEX_GLOW' | 'GRID_FIELD' | 'DOMAIN' | 'SPRITE' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'STREAK' | 'RING' | 'CRACKS' | 'PEBBLE' | 'RUBBLE' | 'SPIKE' | 'DUST' | 'ATMOSPHERE' | 'MAGIC_CIRCLE' | 'GENERIC_DEBUG' | 'SLASH' | 'BLACK_HOLE';

// Define the "Verbs" of our visual language
export type VFXActionType = 
    | 'PARTICLE'    // Spawn an emitter
    | 'BEAM'        // Draw a line/laser
    | 'SHAKE'       // Camera trauma
    | 'GRID_PULSE'  // Floor ripple
    | 'HEAVEN_FALL' // High-altitude impact object
    | 'WAIT';       // Delay next action

export interface VFXAction {
    type: VFXActionType;
    delay?: number;        // Start time relative to sequence start
    id?: string;           // Asset/VFX Registry ID
    style?: string;        // Procedural Style Key
    color?: string;        // Optional override
    scale?: number;        
    duration?: number;
    height?: number;       // For HeavenFall or Pillars
    shakeIntensity?: number;
}

/**
 * The core ECS Component for Skill Visuals
 */
export interface VFXSequence {
    id: string;
    actions: VFXAction[];
}

// Add Range type
export type Range = [number, number];

// Add EmitterConfig type
export interface EmitterConfig {
    particleType: ParticleType;
    count: Range | number;
    speed: Range | number;
    lifetime: Range | number;
    delay: Range | number;
    size: Range | number;
    height?: Range | number;
    colors: string[];
    shape: 'POINT' | 'BURST_DIR' | 'CIRCLE';
    shapeRadius?: number;
    visualStyle?: string;
    drag?: number;
    locked?: boolean;
    gravity?: number;
    vRotation?: Range | number;
    // Added vz property to support explicit vertical velocity in registry definitions
    vz?: Range | number;
    blendMode?: GlobalCompositeOperation;
}

// Add VFXAsset type
export interface VFXAsset {
    id: string;
    description?: string;
    emitters: EmitterConfig[];
}

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};
const GROUND_PARTICLES = new Set([
    'SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 
    'HEX_GLOW', 'PILLAR', 'DOMAIN', 'BLACK_HOLE'
]);
const FIXED_ORIENTATION_PARTICLES = new Set([
    'GRID_FIELD', 'PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX', 'BLACK_HOLE'
]);
const PROCEDURAL_TYPES = new Set([
    'PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE', 
    'DEATH_RAY', 'SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW', 'BLACK_HOLE'
]);
export class VFXPlayer {
    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        const asset = VFX_REGISTRY[effectId];
        if (!asset) return;
        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride, groundZ);
        }
    }
    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string, groundZ?: number) {
        const count = Math.floor(rnd(config.count));
        const isGroundType = GROUND_PARTICLES.has(config.particleType);
        const effectiveZ = (isGroundType && groundZ !== undefined) ? groundZ : cz;
        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = effectiveZ;
            const speed = rnd(config.speed);
            if (config.shape === 'POINT') {} 
            else if (config.shape === 'BURST_DIR') {
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);
                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); 
            }
            else if (config.shape === 'CIRCLE') {
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;
                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }
            if (config.vz !== undefined) {
                vz = rnd(config.vz);
            }
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;
            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);
            p.size = rnd(config.size);
            if (config.height !== undefined) p.height = rnd(config.height);
            p.color = colorOverride || pickColor(config.colors);
            p.type = config.particleType as any;
            if (config.visualStyle) p.style = config.visualStyle;
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.gravity !== undefined) p.gravity = config.gravity;
            if (config.vRotation) {
                p.vRotation = rnd(config.vRotation);
            } else {
                p.vRotation = FIXED_ORIENTATION_PARTICLES.has(config.particleType) ? 0 : (Math.random() - 0.5) * 10;
            }
            if (config.blendMode) p.blendMode = config.blendMode;
            if (!p.image && !PROCEDURAL_TYPES.has(p.type)) {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }
            system.state.particles.push(p);
        }
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

export const ProceduralPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        // 1. 處理地面法陣類 (Locked to Ground)
        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE', 'BLACK_HOLE'].includes(p.type)) {
            // 使用 now * vRotation 確保動畫平滑，不跳幀
            const animRot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, animRot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, animRot, layout);
            } else if (p.type === 'BLACK_HOLE') {
                this.drawBlackHole(ctx, p, progress, now, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, animRot, progress, layout);
            }
        }
        // 2. 處理體積投射類 (3D Entities)
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress, now);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    drawBlackHole(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout) {
        // Animation Curve: Explosive Expansion -> Hold -> Collapse
        let scale = 1.0;
        if (progress < 0.2) scale = progress / 0.2; // Fast Open
        else if (progress > 0.8) scale = (1 - progress) / 0.2; // Fast Close

        const size = p.size * scale;
        if (size < 1) return;

        // 1. Accretion Disk (The "Frisbee")
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y); // Flatten to ground

        const rot = now * 3.0; // High speed rotation
        ctx.rotate(rot);

        // Dynamic Spiral Gradient
        const grad = ctx.createRadialGradient(0, 0, size * 0.3, 0, 0, size);
        grad.addColorStop(0, 'rgba(0,0,0,1)'); // Inner dark
        grad.addColorStop(0.2, p.color);       // Horizon light
        grad.addColorStop(0.5, 'rgba(0,0,0,0.8)'); // Accretion gap
        grad.addColorStop(0.8, p.color);       // Outer ring
        grad.addColorStop(1, 'transparent');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, size, 0, Math.PI*2); ctx.fill();

        // Matter Streaks (Spiral Arms)
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        const arms = 3;
        for(let i=0; i<arms; i++) {
            const offset = i * (Math.PI*2/arms);
            for(let r=size*0.3; r<size; r+=5) {
                const a = offset + (r/size) * 4; // Spiral factor
                const x = Math.cos(a) * r;
                const y = Math.sin(a) * r;
                if(r===size*0.3) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
        }
        ctx.stroke();
        ctx.restore();

        // 2. The Event Horizon (The Sphere)
        // Must appear perfectly round (Sphere), so we undo the ISO scale for the core
        const coreSize = size * 0.3;

        ctx.save();
        // Since we didn't scale Y in the main context yet (only in the save block above),
        // we are still in screen space here.

        // Black Core (Eats Light)
        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = '#000000';
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20 * scale;
        ctx.beginPath(); ctx.arc(0, 0, coreSize, 0, Math.PI*2); ctx.fill();

        // Photon Ring (White Rim)
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1.5;
        ctx.shadowBlur = 5;
        ctx.stroke();

        // Vertical Jets (Optional, adds 3D feel)
        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = p.color;
        ctx.globalAlpha = 0.3 * scale;
        const jetH = size * 1.5;
        const jetW = coreSize * 0.4;
        ctx.fillRect(-jetW/2, -jetH, jetW, jetH * 2);

        ctx.restore();
    },

    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';

        // A. 擴散光環
        ctx.save();
        ctx.globalAlpha = 0.4 * (1 - p.life/p.maxLife);
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 40;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 1.2, rot * 0.5, true, layout);
        ctx.fillStyle = p.color;
        ctx.fill();
        ctx.restore();

        // B. 主幾何體 (高能核心)
        const grad = ctx.createRadialGradient(0,0,0, 0,0, p.size);
        grad.addColorStop(0, '#ffffff');
        grad.addColorStop(0.3, p.color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        // C. 邊緣外框 (銳利化)
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 15;

        // 多層環繞幾何
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.save();
        ctx.setLineDash([10, 5]);
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.85, -rot * 1.2, true, layout);
        ctx.stroke();
        ctx.restore();

        // 中心符文脈衝
        const pulse = 0.5 + Math.sin(rot * 2) * 0.2;
        ctx.globalAlpha = pulse;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.4, rot * 3, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.6;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number) {
        const h = p.height || 1000; 
        const w = p.size * (1 - progress * 0.5);
        const color = p.color;

        ctx.globalCompositeOperation = 'screen';

        // 核心漸變
        const grad = ctx.createLinearGradient(-w/2, 0, w/2, 0);
        grad.addColorStop(0, color); 
        grad.addColorStop(0.5, '#ffffff'); 
        grad.addColorStop(1, color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.fillRect(-w/2, -h, w, h);

        // 掃描線動畫 (TA 增加)
        const scanY = -( (now * 500) % h );
        ctx.fillStyle = '#ffffff';
        ctx.globalAlpha = 0.3 * (1 - progress);
        ctx.fillRect(-w/2, scanY, w, 2);

        // 底部圓盤
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const glow = ctx.createRadialGradient(0,0,0, 0,0, w * 2);
        glow.addColorStop(0, '#fff');
        glow.addColorStop(1, 'transparent');
        ctx.fillStyle = glow;
        ctx.globalAlpha = (1 - progress) * 0.5;
        ctx.beginPath(); ctx.arc(0, 0, w * 2, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size;
        const h = 80;
        const opacity = 0.4 * (1 - progress);
        // 使用 3D 棱鏡繪製區域感
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

import { Particle } from "../state";
import { BillboardPainter } from "./painters/BillboardPainter";
import { GroundPainter } from "./painters/GroundPainter";
import { ProceduralPainter } from "./painters/ProceduralPainter";
import { HexLayout } from "../../../../types";

// Static categorization for faster dispatch
const PROCEDURAL_SET = new Set(['PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'DOMAIN', 'DEATH_RAY', 'BEAM', 'MAGIC_CIRCLE', 'BLACK_HOLE']);
const GROUND_PLANE_SET = new Set(['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'HEX_GLOW']);

/**
 * Unified Particle Dispatcher v8.6
 */
export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean, layout: HexLayout) {
        const now = Date.now() / 1000;

        // 1. Vectorized Procedural Logic (Pillars, Domains, Beams)
        if (PROCEDURAL_SET.has(p.type)) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ProceduralPainter.draw(ctx, p, progress, now, layout);
            ctx.restore();
            return;
        }

        // 2. Ground Projection Logic (Ripples, Cracks, Fields)
        if (GROUND_PLANE_SET.has(p.type)) {
            GroundPainter.draw(ctx, p, progress, drawX, drawY, layout);
            return;
        }

        // 3. Billboard Sprites (Smoke, Sparks, Debris, Rocks)
        if (p.type !== 'GENERIC_DEBUG') {
            BillboardPainter.draw(ctx, p, drawX, drawY, progress);
        } else {
            // 4. Critical Safe Fallback
            ctx.save();
            ctx.translate(drawX, drawY);
            ctx.fillStyle = '#ff00ff';
            ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

