    const activePointers = useRef<Set<number>>(new Set());
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);
    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };
    const handlePointerDown = (e: PointerEvent) => {
        activePointers.current.add(e.pointerId);
        if (activePointers.current.size > 1) { interactionMode.current = 'IDLE'; return; }
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        const cvs = canvasRef.current;
        if (!cvs) return;
        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        const h = getHexFromCoords(sx, sy);
        const agent = h ? engine.getAgentAt(h.q, h.r) : undefined;

        // FIX: Removed !engine.isRunning check to allow unit selection/inspection during combat
        if (agent) { 
            pressedAgentRef.current = agent; 
            setPressedAgent(agent); 
        }
        else if (h && !engine.isRunning && configRef.current.tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
            const obsType = engine.map.obstacles.get(HexUtils.key(h));
            const obj = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            draggedObstacleRef.current = obj;
            setDraggedObstacle(obj);
        }
        interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };
    const handlePointerMove = (e: PointerEvent) => {
        if (!lastPointerPos.current || activePointers.current.size > 1) return;
        const cvs = canvasRef.current;
        if (!cvs) return;
        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left, sy = e.clientY - rect.top;
        const dx = sx - lastPointerPos.current.x, dy = sy - lastPointerPos.current.y;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Vector.dist(pressStartPos.current, {x: sx, y: sy});
            if (dist > 8) {
                if (!engine.isRunning && configRef.current.tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) interactionMode.current = 'DRAG_UNIT';
                    else if (draggedObstacleRef.current) { 
                        interactionMode.current = 'DRAG_OBS'; 
                        engine.map.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR); 
                    }
                    else interactionMode.current = 'PAN';
                } else if (!engine.isRunning && configRef.current.tool !== ToolType.SELECT) interactionMode.current = 'PAINT';
                else interactionMode.current = 'PAN';
            }
        }
        if (interactionMode.current === 'PAN') { if (engine.renderer?.camera) engine.renderer.camera.applyPanOffset(dx, dy); cvs.style.cursor = 'move'; }
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2, cy = rect.height / 2;
            const terrainH = h ? rendererRef.current.getTerrainHeight(h.q, h.r, engine) : 0;
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY + terrainH;
            cvs.style.cursor = 'grabbing';
        }
        else if (interactionMode.current === 'PAINT' && h) executePaintAction(h);
        lastPointerPos.current = { x: sx, y: sy };
    };
    const handlePointerUp = (e: PointerEvent) => {
        activePointers.current.delete(e.pointerId);
        const cvs = canvasRef.current;
        if (!cvs) return;
        if (interactionMode.current === 'DOWN') onSelect(pressedAgentRef.current);
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id)) { engine.updateAgentPosition(a, h.q, h.r); const p = HexUtils.toPx(h.q, h.r, engine.mapConfig); a.px = p.x; a.py = p.y; }
            else { const p = HexUtils.toPx(a.q, a.r, engine.mapConfig); a.px = p.x; a.py = p.y; }
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r)) engine.map.setObstacle(h.q, h.r, draggedObstacleRef.current.type);
            else engine.map.setObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR, draggedObstacleRef.current.type);
        }
        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null; setPressedAgent(null);
        draggedObstacleRef.current = null; setDraggedObstacle(null);
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };
    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;
        if (tool === ToolType.DELETE) { engine.map.removeObstacle(h.q, h.r); engine.removeAgent(h.q, h.r); }
        else if (tool === ToolType.OBSTACLE) { engine.removeAgent(h.q, h.r); engine.map.setObstacle(h.q, h.r, selectedObstacle); }
        else if (tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED) {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent = engine.addAgent(tool === ToolType.ADD_BLUE ? Team.BLUE : Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') { agent.role = draftRole; agent.saveState(); agent.reset(engine.mapConfig); }
            }
        }
    };
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;
        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);
        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);
    return { hoveredHexRef, pressedAgent, draggedObstacle };
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { VFXFactory } from "../VFXFactory";
import { HexGeometry } from "../utils/HexGeometry";
import { HexLayout } from "../../../types";

export const SurfacePainter = {

    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number,
        layout: HexLayout = 'FLAT' 
    ) {
        ctx.save();
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.9 * intensity;
        ctx.fill();

        ctx.clip(); 

        const flowX = Math.sin(time * 0.5) * 8;
        const flowY = Math.cos(time * 0.4) * 8;

        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.ellipse(flowX, flowY, r * 0.6, r * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.3;

        const bubbleX = Math.cos(time * 0.8) * (r * 0.4);
        const bubbleY = Math.sin(time * 0.9) * (r * 0.4) * ISO_SCALE_Y;

        ctx.beginPath(); 
        ctx.arc(bubbleX, bubbleY, r * 0.3, 0, Math.PI * 2); 
        ctx.fill();

        ctx.restore();
    },

    /**
     * 高能見度草地渲染器 v2.0
     * 解決與地表顏色過於貼近的問題
     */
    drawGrass(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string, // 地表頂層色 (theme.top)
        density: number, 
        time: number
    ) {
        ctx.save();
        ctx.translate(x, y);

        const seed = Math.sin(x * 0.12 + y * 0.12);
        const windForce = Math.sin(time * 1.5 + x * 0.02) * 8;

        const tufts = [
            { x: -12, y: -4,  scale: 1.1, offset: 0 },
            { x: 10,  y: 2,   scale: 0.9, offset: 2 },
            { x: -2,  y: 12,  scale: 1.2, offset: 4 }
        ];

        for (let i = 0; i < tufts.length; i++) {
            const t = tufts[i];
            const localSeed = seed + i;
            const bx = t.x + Math.cos(localSeed * 5) * 4;
            const by = t.y + Math.sin(localSeed * 5) * 4;

            // 1. 根部陰影 pass (解決「浮」在空中的問題)
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath();
            ctx.ellipse(bx, by, 6 * t.scale, 3 * t.scale, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();

            // 2. 繪製草葉主體 (稍微提亮地表色)
            ctx.save();
            this.pathTuft(ctx, bx, by, windForce, t.scale);

            const grad = ctx.createLinearGradient(bx, by, bx + windForce * 0.5, by - 15 * t.scale);
            grad.addColorStop(0, 'rgba(0,0,0,0.5)'); // 根部深色
            grad.addColorStop(0.4, color);           // 中段地表色
            grad.addColorStop(1, '#ffffff');         // 葉尖高亮

            ctx.fillStyle = grad;
            ctx.shadowColor = 'rgba(0,0,0,0.3)';
            ctx.shadowBlur = 2;
            ctx.fill();

            // 3. 邊緣勾勒 (AO 效果)
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.lineWidth = 0.5;
            ctx.stroke();

            ctx.restore();
        }

        ctx.restore();
    },

    pathTuft(ctx: CanvasRenderingContext2D, bx: number, by: number, wind: number, scale: number) {
        const h = 16 * scale;
        const w = 5 * scale;

        const tipX = bx + wind * scale;
        const tipY = by - h;

        ctx.beginPath();
        ctx.moveTo(bx - w, by);
        // 增加一個貝茲曲線控制點讓葉片有厚度感
        ctx.quadraticCurveTo(bx - w * 0.8, by - h * 0.5, tipX, tipY);
        ctx.quadraticCurveTo(bx + w * 0.8, by - h * 0.5, bx + w, by);
        ctx.closePath();
    },

    drawIceSheen(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        time: number,
        layout: HexLayout = 'FLAT'
    ) {
        ctx.save();
        ctx.translate(x, y);
        HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
        ctx.clip();
        const slide = (time * 0.5) % 2.5 - 0.7; 
        const w = size * 2;
        const grad = ctx.createLinearGradient(-w, -w, w, w);
        const start = slide - 0.3;
        const end = slide + 0.3;
        grad.addColorStop(Math.max(0, Math.min(1, start)), 'rgba(255,255,255,0)');
        grad.addColorStop(Math.max(0, Math.min(1, slide)), 'rgba(255,255,255,0.25)'); 
        grad.addColorStop(Math.max(0, Math.min(1, end)), 'rgba(255,255,255,0)');
        ctx.fillStyle = grad;
        ctx.fillRect(-size, -size, size*2, size*2);
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-5, 5); ctx.lineTo(5, -5);
        ctx.moveTo(2, 8); ctx.lineTo(8, 4);
        ctx.stroke();
        ctx.restore();
    },

    drawSandRipples(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.15; 
        const seed = Math.sin(x * 0.05 + y * 0.05);
        const offset = seed * 5;
        for(let i=-1; i<=1; i++) {
            const ly = i * 8 + offset;
            ctx.beginPath();
            for(let lx=-15; lx<=15; lx+=5) {
                const wave = Math.sin(lx * 0.3 + offset) * 2;
                if(lx === -15) ctx.moveTo(lx, ly + wave);
                else ctx.lineTo(lx, ly + wave);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.2;
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.12; 
        const puffs = 4;
        const twoPi = Math.PI * 2;
        for(let i=0; i<puffs; i++) {
            const angle = time * 0.15 + (i * twoPi / puffs);
            const dist = 15 + Math.sin(time * 0.8 + i) * 8;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;
            const pulse = 1.0 + Math.sin(time * 1.2 + i) * 0.15;
            const pSize = size * 0.55 * pulse;
            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }
        ctx.globalAlpha = 0.18;
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.4; 
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;
        ctx.rotate((x * 0.001) + (y * 0.001)); 
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        const variant = Math.abs(Math.floor(seed * 100));
        const texture = VFXFactory.getTerrainDetail(type, color, variant);
        const size = texture.width;
        ctx.drawImage(texture, x - size/2, y - size/2);
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() { this.cache.clear(); }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        if (['DUST', 'PEBBLE', 'CHIP', 'RUBBLE', 'DEBRIS', 'SHARD'].includes(type)) type = 'ROCK';
        if (['CLOUD', 'SMOKE_PUFF', 'MUSHROOM'].includes(type)) type = 'SMOKE';
        if (['GLOW', 'FLARE', 'CORE', 'ATMOSPHERE'].includes(type)) type = 'GLOW_SPRITE';

        const key = `T92_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);
        const r = 40; 

        switch (type) {
            case 'SMOKE': ParticlePainter.drawSmoke(ctx, r, color); break;
            case 'GLOW_SPRITE': ParticlePainter.drawAtmosphere(ctx, r, color); break;
            case 'SPIKE':
            case 'SPARK': ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color); break;
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_LOCK': IconPainter.drawHexLock(ctx, r, color); break;
            case 'SHADOW_BLOB':
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, color); 
                grad.addColorStop(0.6, 'rgba(0,0,0,0.3)');
                grad.addColorStop(1, 'transparent'); 
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
                break;
            case 'CRACKS': ParticlePainter.drawCracks(ctx, r, color); break;
            case 'SLASH': ParticlePainter.drawSlash(ctx, r, color); break;
            case 'BEAM':
                const beamGrad = ctx.createLinearGradient(0, -60, 0, 60);
                beamGrad.addColorStop(0, 'transparent');
                beamGrad.addColorStop(0.2, color);
                beamGrad.addColorStop(0.8, color);
                beamGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = beamGrad;
                ctx.fillRect(-10, -60, 20, 120);
                break;
            default:
                ctx.fillStyle = '#ff00ff';
                ctx.fillRect(-5,-5,10,10);
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    /**
     * 優化方案：預渲染草叢精靈，避免每幀重複建立漸層與計算路徑
     */
    public getGrassSprite(color: string, variant: number): HTMLCanvasElement {
        const key = `GRASS_${color}_${variant}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(64, 64);
        ctx.translate(32, 48); // 底部中心對齊

        const scale = 0.8 + (variant % 5) * 0.1;
        const h = 22 * scale;
        const w = 6 * scale;

        // 1. 預渲染陰影 (不使用 shadowBlur，改用漸層圓)
        const shadowGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, w * 2);
        shadowGrad.addColorStop(0, 'rgba(0,0,0,0.35)');
        shadowGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = shadowGrad;
        ctx.save();
        ctx.scale(1, 0.5);
        ctx.beginPath(); ctx.arc(0, 0, w * 2, 0, Math.PI * 2); ctx.fill();
        ctx.restore();

        // 2. 預渲染葉片主體
        const grassGrad = ctx.createLinearGradient(0, 0, 0, -h);
        grassGrad.addColorStop(0, 'rgba(0,0,0,0.4)'); // 根部深色
        grassGrad.addColorStop(0.5, color);           // 中段主色
        grassGrad.addColorStop(1, '#ffffff');         // 葉尖高亮

        ctx.fillStyle = grassGrad;
        ctx.beginPath();
        ctx.moveTo(-w, 0);
        ctx.quadraticCurveTo(-w * 0.5, -h * 0.5, 0, -h);
        ctx.quadraticCurveTo(w * 0.5, -h * 0.5, w, 0);
        ctx.closePath();
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('GLOW_SPRITE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }
    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const key = `DETAIL_${type}_${color}_${variant}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(HEX_SIZE * 2, HEX_SIZE * 2);
        ctx.translate(HEX_SIZE, HEX_SIZE);

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.3;

        if (type === 'FOREST') {
            ctx.beginPath();
            ctx.moveTo(0, -10);
            ctx.lineTo(8, 5);
            ctx.lineTo(-8, 5);
            ctx.closePath();
            ctx.fill();
        } else if (type === 'VOID') {
            ctx.beginPath();
            for(let i=0; i<4; i++) {
                const angle = i * Math.PI / 2;
                ctx.moveTo(0,0);
                ctx.lineTo(Math.cos(angle)*8, Math.sin(angle)*8);
            }
            ctx.strokeStyle = color;
            ctx.stroke();
        }

        this.cache.set(key, canvas);
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { VFXFactory } from "../VFXFactory";
import { HexGeometry } from "../utils/HexGeometry";
import { HexLayout } from "../../../types";

export const SurfacePainter = {

    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number,
        layout: HexLayout = 'FLAT' 
    ) {
        ctx.save();
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.9 * intensity;
        ctx.fill();

        ctx.clip(); 

        const flowX = Math.sin(time * 0.5) * 8;
        const flowY = Math.cos(time * 0.4) * 8;

        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.ellipse(flowX, flowY, r * 0.6, r * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.3;

        const bubbleX = Math.cos(time * 0.8) * (r * 0.4);
        const bubbleY = Math.sin(time * 0.9) * (r * 0.4) * ISO_SCALE_Y;

        ctx.beginPath(); 
        ctx.arc(bubbleX, bubbleY, r * 0.3, 0, Math.PI * 2); 
        ctx.fill();

        ctx.restore();
    },

    /**
     * 高效能草地渲染器 v3.0 (Sprite Based)
     * 使用預渲染精靈取代即時幾何計算
     */
    drawGrass(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string, 
        density: number, 
        time: number
    ) {
        ctx.save();
        ctx.translate(x, y);

        // 數學風力偏移：僅在 drawImage 時應用微小的 skew 或 translation，效能極高
        const windX = Math.sin(time * 1.2 + x * 0.05) * 4;

        const tufts = [
            { x: -14, y: -2,  v: 1 },
            { x: 12,  y: 4,   v: 2 },
            { x: -2,  y: 14,  v: 3 }
        ];

        for (let i = 0; i < tufts.length; i++) {
            const t = tufts[i];
            const sprite = VFXFactory.getGrassSprite(color, t.v);

            // 繪製預渲染的草叢 (含陰影與高光)
            // skrew 效果模擬風吹，比重新 pathTuft 快數百倍
            ctx.drawImage(sprite, t.x + windX - 32, t.y - 48);
        }

        ctx.restore();
    },

    drawIceSheen(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        time: number,
        layout: HexLayout = 'FLAT'
    ) {
        ctx.save();
        ctx.translate(x, y);
        HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
        ctx.clip();
        const slide = (time * 0.5) % 2.5 - 0.7; 
        const w = size * 2;
        const grad = ctx.createLinearGradient(-w, -w, w, w);
        const start = slide - 0.3;
        const end = slide + 0.3;
        grad.addColorStop(Math.max(0, Math.min(1, start)), 'rgba(255,255,255,0)');
        grad.addColorStop(Math.max(0, Math.min(1, slide)), 'rgba(255,255,255,0.25)'); 
        grad.addColorStop(Math.max(0, Math.min(1, end)), 'rgba(255,255,255,0)');
        ctx.fillStyle = grad;
        ctx.fillRect(-size, -size, size*2, size*2);
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-5, 5); ctx.lineTo(5, -5);
        ctx.moveTo(2, 8); ctx.lineTo(8, 4);
        ctx.stroke();
        ctx.restore();
    },

    drawSandRipples(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.15; 
        const seed = Math.sin(x * 0.05 + y * 0.05);
        const offset = seed * 5;
        for(let i=-1; i<=1; i++) {
            const ly = i * 8 + offset;
            ctx.beginPath();
            for(let lx=-15; lx<=15; lx+=5) {
                const wave = Math.sin(lx * 0.3 + offset) * 2;
                if(lx === -15) ctx.moveTo(lx, ly + wave);
                else ctx.lineTo(lx, ly + wave);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.2;
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.12; 
        const puffs = 4;
        const twoPi = Math.PI * 2;
        for(let i=0; i<puffs; i++) {
            const angle = time * 0.15 + (i * twoPi / puffs);
            const dist = 15 + Math.sin(time * 0.8 + i) * 8;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;
            const pulse = 1.0 + Math.sin(time * 1.2 + i) * 0.15;
            const pSize = size * 0.55 * pulse;
            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }
        ctx.globalAlpha = 0.18;
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.4; 
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;
        ctx.rotate((x * 0.001) + (y * 0.001)); 
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        const variant = Math.abs(Math.floor(seed * 100));
        const texture = VFXFactory.getTerrainDetail(type, color, variant);
        const size = texture.width;
        ctx.drawImage(texture, x - size/2, y - size/2);
    }
};

