function easeAttack(t: number): number {
    if (t < 0.45) {
        const p = t / 0.45;
        return -0.5 * (p * p * p); 
    } else if (t < 0.55) {
        const p = (t - 0.45) / 0.1;
        return -0.5 + (1.7 * p); 
    } else {
        const p = (t - 0.55) / 0.45;
